    def get_staged_plan_file_with_planid(self, plan_id):
        staged_plans = self.pe_api.get_plan_list()

        for plan in staged_plans:
            if plan.plan_id == plan_id:
                action_id = self._generate_plan_file(plan.plan_id)
                return self.pe_api.upload_file(self._get_plans_file_name(plan_id, action_id))

        raise FileNotFound(f"Plan with provided {plan_id} plan id is not present in staged plans")

    def _generate_plan_file(self, plan_id):
        plan_upload_options = PlanUploadOptions(delta_change_only=False)
        generate_plan_response = self.pe_api.generate_plan_file_for_uploading(plan_id=plan_id,
                                                                              plan_upload_options=plan_upload_options)

        if generate_plan_response.status == 'ongoing':
            return generate_plan_response.action_id

        raise WrongApiResponseStatus(f"Request status for generate plan response {generate_plan_response.status}")

    def _get_plans_file_name(self, plan_id, action_id, interval=1, timeout=20):
        endtime = timeout + time.time()
        while time.time() < endtime:
            get_action_state_response = self.pe_api.get_action_state_of_uploading_plan_file(plan_id=plan_id,
                                                                                            action_id=action_id)
            if get_action_state_response.status == 'success':
                return get_action_state_response.file_name
            else:
                time.sleep(interval)

        get_action_state_response = self.pe_api.get_action_state_of_uploading_plan_file(plan_id=plan_id,
                                                                                        action_id=action_id)

        raise WrongApiResponseStatus(f"Request status for get action state response {get_action_state_response.status}")

    def create_vdu_object(self, delta_plan_id, parent_mo_dn, mo_name, timeout=30, include_defaults=True):
        parent_mo_uuid = self._get_mouuid(delta_plan_id, parent_mo_dn, timeout=timeout)
        class_nidd = self._get_mo_nidd(mo_name, timeout=timeout)
        instance_id = int(mo_name.split('-')[-1])

        create_object_request = CreateObjectRequest(parent_mo_uuid=parent_mo_uuid,
                                                    nidd_id=class_nidd,
                                                    instance_id=instance_id,
                                                    include_defaults=include_defaults)

        return self.pe_api.create_managed_object_of_delta_plan(plan_id=delta_plan_id,
                                                               create_object_request=create_object_request,
                                                               _request_timeout=timeout)

    def _get_mouuid(self, plan_id, mo_dn, timeout=30):
        delta_plan_tree = self.pe_api.get_tree_of_delta_plan(plan_id=plan_id, _request_timeout=timeout).created
        name_list = mo_dn.split('/')

        parent_mouuid = ''
        for name in name_list:
            for mo_info in delta_plan_tree:
                if mo_info.parent_mo_uuid is None:
                    parent_mo_in_plan = ''
                else:
                    parent_mo_in_plan = mo_info.parent_mo_uuid
                if parent_mo_in_plan == parent_mouuid and mo_info.name == name:
                    parent_mouuid = mo_info.mo_uuid
                    break

        return parent_mouuid

    def _get_mo_nidd(self, mo_name, timeout=30):
        for nidd_definition in self.get_nidd()["managedObjects"]:
            if nidd_definition["className"] == mo_name.split('-')[0]:
                return nidd_definition["niddId"]

        return None

    def get_create_vdu_object_action_status(self, plan_id, action_id, timeout=30):
        return self.pe_api.get_create_managed_object_of_delta_plan_action(plan_id=plan_id,
                                                                          action_id=action_id,
                                                                          _request_timeout=timeout)

    def update_vdu_parameter(self, plan_id, mo_dn, updated_paras_dict, operation='replace', mo_uuid=None, timeout=30):
        if mo_uuid is None:
            mo_uuid = self._get_mouuid(plan_id=plan_id, mo_dn=mo_dn, timeout=timeout)

        changes_list = []
        for para_name, para_value in updated_paras_dict.items():
            if not para_name.startswith('/'):
                para_name = '/' + para_name

            changes_list.append(ManagedObjectPayloadChange(op=operation, path=para_name, value=para_value))

        update_para_request = UpdateParametersRequest(mo_uuid=mo_uuid, changes=changes_list)
        return self.pe_api.update_parameters_of_delta_plan(plan_id=plan_id,
                                                           update_parameters_request=update_para_request,
                                                           _request_timeout=timeout)

    def get_update_paras_action_status(self, plan_id, action_id, timeout=30):
        return self.pe_api.get_update_parameters_of_delta_plan_action(plan_id=plan_id,
                                                                      action_id=action_id,
                                                                      _request_timeout=timeout)

    def get_delta_plan_info_list(self, timeout=30):
        return self.pe_api.get_delta_plan_list(_request_timeout=timeout)

    def delete_delta_plan_file(self, plan_id, timeout=None):
        self.local_client.delete_delta_plan_file(plan_id=plan_id, timeout=timeout)

    def generate_delta_plan(self, plan_name, plan_description=None, timeout=30):
        return self.pe_api.generate_delta_plan(plan_info_request=PlanInfoRequest(plan_name=plan_name,
                                                                                 plan_description=plan_description),
                                               _request_timeout=timeout)

    def get_delta_plan_generated_action_status(self, action_id, timeout=30):
        return self.pe_api.get_action_state_of_generating_delta_plan(action_id=action_id,
                                                                     _request_timeout=timeout)

    def save_delta_plan_file(self, timeout=30):
        delta_plans = self.get_delta_plan_info_list(timeout=30)

        if delta_plans:
            delta_plan_id = delta_plans[0].plan_id
            action_id = self._generate_delta_plan_file(delta_plan_id, timeout=30)
            return self.pe_api.upload_file(self._get_delta_plan_file_name(plan_id=delta_plan_id,
                                                                          action_id=action_id,
                                                                          timeout=timeout))

        raise FileNotFound("No delta plans found")

    def _generate_delta_plan_file(self, plan_id, timeout=30):
        plan_upload_options = PlanUploadOptions(delta_change_only=True)
        generate_delta_plan_response = self.pe_api.generate_delta_plan_file_for_uploading(plan_id=plan_id,
                                                                                          plan_upload_options=plan_upload_options,
                                                                                          _request_timeout=timeout)

        if generate_delta_plan_response.status == 'ongoing':
            return generate_delta_plan_response.action_id

        raise WrongApiResponseStatus(f"Request status for generate plan response {generate_delta_plan_response.status}")

    def _get_delta_plan_file_name(self, plan_id, action_id, interval=1, timeout=30):
        endtime = timeout + time.time()
        while time.time() < endtime:
            get_action_state_res = self.pe_api.get_action_state_of_uploading_delta_plan_file(plan_id=plan_id,
                                                                                             action_id=action_id,
                                                                                             _request_timeout=30)
            if get_action_state_res.status == 'success':
                return get_action_state_res.file_name
            else:
                time.sleep(interval)

        get_action_state_res = self.pe_api.get_action_state_of_uploading_delta_plan_file(plan_id=plan_id,
                                                                                         action_id=action_id,
                                                                                         _request_timeout=30)
        try:
            error_msg = (f"The status of uploading delta plan file is {get_action_state_res.status}, "
                         f"error message is - {get_action_state_res.error_message}.")
        except Exception:
            error_msg = f"Request status for get action state response {get_action_state_res.status}"

        raise WrongApiResponseStatus(error_msg)

    @staticmethod
    def _search_complex_parameter(parameter_info, para_name_list):
        complex_value = parameter_info.complex_parameter.value[int(para_name_list[1])]

        for parameter in complex_value.structure_parameters:
            parameter_type = parameter.parameter_type
            if parameter_type == 'simple' and parameter.simple_parameter.name == para_name_list[-1]:
                return parameter.simple_parameter.value

            if parameter_type == 'simpleList' and parameter.simple_list_parameter.name == para_name_list[-1]:
                return parameter.simple_list_parameter.value

        return None

    def _search_parameter_in_current_plan(self, para_name_list, mo_dn, timeout=30):  # noqa: C901
        # TODO: Functionality should be modified when transitioning to internal HTTP client
        response = self.pe_api.search_parameters_of_current_plan(page_number=1,
                                                                 items_per_page=50,
                                                                 sort_order='asc',
                                                                 filter_by_name=para_name_list[-1],
                                                                 sorted_by='parameterFullName',
                                                                 _request_timeout=timeout)
        if response.total > 50:
            response = self.pe_api.search_parameters_of_current_plan(page_number=1,
                                                                     items_per_page=response.total,
                                                                     sort_order='asc',
                                                                     filter_by_name=para_name_list[-1],
                                                                     sorted_by='parameterFullName',
                                                                     _request_timeout=timeout)

        for para in response.items:
            if para.distname == mo_dn and para.parameter_name == para_name_list[0]:
                parameter_info = para.parameter
                parameter_type = parameter_info.parameter_type

                if parameter_type == 'simple':
                    return parameter_info.simple_parameter.value

                if parameter_type == 'simpleList':
                    return parameter_info.simple_list_parameter.value

                if parameter_type == 'complex':
                    return self._search_complex_parameter(parameter_info, para_name_list)

        return None

    def search_parameter_of_current_plan(self, mo_dn, para_name, timeout=30):
        info = self._search_parameter_in_current_plan(para_name_list=para_name.split('/'),
                                                      mo_dn=mo_dn,
                                                      timeout=timeout)

        if info:
            return info

        raise WrongApiResponseStatus(f"Not found the parameter - {para_name} under {mo_dn}")

