    def update_vdu_parameter_of_staged_plan(self, plan_id, mo_dn, updated_paras_dict, operation='replace',
                                            mo_uuid=None, timeout=30):
        if mo_uuid is None:
            mo_uuid = self._get_mouuid_of_staged_plan(plan_id=plan_id, mo_dn=mo_dn, timeout=timeout)

        changes_list = []
        for para_name, para_value in updated_paras_dict.items():
            if not para_name.startswith('/'):
                para_name = '/' + para_name
            changes_list.append(ManagedObjectPayloadChange(op=operation, path=para_name, value=para_value))

        update_para_request = UpdateParametersRequest(mo_uuid=mo_uuid, changes=changes_list)

        return self.pe_api.update_parameters(plan_id=plan_id,
                                             update_parameters_request=update_para_request,
                                             _request_timeout=timeout)

    def _get_mouuid_of_staged_plan(self, plan_id, mo_dn, timeout=30):
        staged_plan_tree = self.pe_api.get_tree_of_staged_plan(plan_id=plan_id, _request_timeout=timeout).created
        name_list = mo_dn.split('/')
        parent_mouuid = ''

        for name in name_list:
            for mo_info in staged_plan_tree:
                if mo_info.parent_mo_uuid is None:
                    parent_mo_in_plan = ''
                else:
                    parent_mo_in_plan = mo_info.parent_mo_uuid

                if parent_mo_in_plan == parent_mouuid and mo_info.name == name:
                    parent_mouuid = mo_info.mo_uuid
                    break

