    def get_remote_snapshot(self, log_level, request_timeout=30, operation_timeout=600.0):
        request = CollectSnapshotRequest(coverage=log_level, originator='EM')
        trigger_local_snapshot = self.snapshot_api.trigger_remote_snapshot(collect_snapshot_request=request,
                                                                           _request_timeout=request_timeout)

        operation_id = trigger_local_snapshot.operation_id
        start = time.time()
        self._try_getting_remote_snapshot_operation(operation_id=operation_id,
                                                    start_time=start,
                                                    request_timeout=request_timeout,
                                                    operation_timeout=operation_timeout)

        self.snapshot_api.delete_remote_snapshot_operation(operation_id=operation_id)

        check_if_snapshot_operation_finished(instance=self,
                                             start_time=start,
                                             operation_timeout=operation_timeout,
                                             request_timeout=request_timeout)

    def _try_getting_remote_snapshot_operation(self, operation_id, start_time, request_timeout, operation_timeout):
        while time.time() - start_time < operation_timeout:
            remote_snapshot_response = self.snapshot_api.get_remote_snapshot_operation(operation_id,
                                                                                       _request_timeout=request_timeout)
            if remote_snapshot_response.status == 'failed':
                self.snapshot_api.delete_remote_snapshot_operation(operation_id=operation_id)
                raise WrongApiResponseStatus(remote_snapshot_response.failure_info)

            if remote_snapshot_response.status == 'succeeded':
                return
            time.sleep(1)

        raise TimeoutException("Get remote snapshot timeout.")

